using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithTools<MyTools>()
    .WithResources<MyResources>()
    .WithHttpTransport();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public static class MyTools
{
    [McpServerTool, Description("Adds two numbers together.")]
    public static double Add(double a, double b) => a + b;

    [McpServerTool, Description("Gets the current UTC time.")]
    public static string GetCurrentTime() => DateTime.UtcNow.ToString("o");
}

[McpServerResourceType]
public static class MyResources
{
    [McpServerResource(UriTemplate = "config://app", Name = "AppConfig",
        MimeType = "application/json")]
    [Description("Returns application configuration data.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };
        return System.Text.Json.JsonSerializer.Serialize(config);
    }

    [McpServerResource(UriTemplate = "config://features/{featureName}", Name = "FeatureFlag",
        MimeType = "application/json")]
    [Description("Returns whether a feature flag is enabled.")]
    public static string GetFeatureFlag(string featureName)
    {
        var flags = new Dictionary<string, bool>
        {
            ["dark-mode"] = true,
            ["beta-api"] = false,
            ["caching"] = true,
        };

        var enabled = flags.TryGetValue(featureName, out var value) && value;
        return System.Text.Json.JsonSerializer.Serialize(new { featureName, enabled });
    }
}

